const tx=v=>(Array.isArray(v)?v.map(t=>t.alt).join(' | '):String(v)).replace(/<[^>]+>/g,' ');
const bv=(cur,k,v)=>k==='image_alts'?(cur.images||[]).filter(i=>v.some(t=>t.id===i.id)).map(i=>({id:i.id,alt:i.alt||''})):k.startsWith('rank_math')?((cur.meta_data||[]).find(m=>m.key===k)?.value??''):(raw(cur[k])??'');
const put=async(c,kind,id,fields)=>{const {image_alts,...rest}=fields;const f={},m=[];for(const k in rest)k.startsWith('rank_math')?m.push({key:k,value:rest[k]}):f[k]=rest[k];if(m.length&&kind==='product')f.meta_data=m;
 const rr=await wp(c,BASE[kind]+(id?'/'+id:''),id?'PUT':'POST',f);if(m.length&&kind!=='product')await wp(c,'goli/v1/meta/'+(id||rr.id),'POST',Object.fromEntries(m.map(x=>[x.key,x.value])));for(const t of image_alts||[]){if(!t.id)continue;try{await wp(c,'wp/v2/media/'+t.id,'POST',{alt_text:t.alt})}catch(e){if(!/^404/.test(e.message))throw e}}};
