const te=new TextEncoder(),td=new TextDecoder(),b64=b=>btoa(String.fromCharCode(...new Uint8Array(b))),ub=x=>Uint8Array.from(atob(x),c=>c.charCodeAt(0));
async function dk(pw,salt){const m=await crypto.subtle.importKey('raw',te.encode(pw),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:200000,hash:'SHA-256'},m,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function enc(pw,o){const s=crypto.getRandomValues(new Uint8Array(16)),i=crypto.getRandomValues(new Uint8Array(12));return JSON.stringify({s:b64(s),i:b64(i),c:b64(await crypto.subtle.encrypt({name:'AES-GCM',iv:i},await dk(pw,s),te.encode(JSON.stringify(o))))})}
async function dec(pw,x){const o=JSON.parse(x);return JSON.parse(td.decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:ub(o.i)},await dk(pw,ub(o.s)),ub(o.c))))}
