 const all=async()=>{if(confirm('همه کارت‌های در انتظار اعمال شوند؟'))for(let i=0;i<items.length;i++)if(items[i].state==='pending'&&items[i].a.op!=='delete')await approve(i)};
 const upd=(i,p)=>setItems(l=>l.map((x,j)=>j===i?{...x,...p}:x));
