   <div className="why">{x.a.why}</div>
   {x.warn?.length>0&&<div className="why" style={{color:'#B8325F'}}>⚠ {x.warn.join(' · ')}</div>}{x.warn&&!x.warn.length&&<div className="why">✓ بررسی خودکار سئو بدون هشدار</div>}{x.score!=null&&<div className="why">امتیاز ممیز سئو: <b>{x.score}</b> از ۱۰۰</div>}
   {Object.entries(x.a.fields).map(([k,v])=><div className="f" key={k}><b>{k}</b>
    {x.before[k]!=null&&<div className="old">{tx(x.before[k])}</div>}
    <div className="new">{tx(v)}</div></div>)}
   {(x.a.fields.content||x.a.fields.description)&&<div className="row"><button className="alt" onClick={()=>upd(i,{prev:!x.prev})}>{x.prev?'بستن پیش‌نمایش':'پیش‌نمایش'}</button></div>}
   {x.prev&&<iframe sandbox="" srcDoc={'<div dir="rtl" style="font-family:Tahoma,sans-serif;line-height:1.8">'+(x.a.fields.content||x.a.fields.description)+'</div>'} style={{width:'100%',height:380,border:'1px solid #D5DBD0',borderRadius:6,marginTop:8,background:'#fff'}}/>}
   {x.note&&<div className="why">{x.note}</div>}
