 cards=(items,numbered)=>C({content_width:'full',flex_direction:'row',flex_wrap:'wrap',flex_gap:gap(16)},items.map((i,k)=>C({width:{unit:'%',size:Math.floor(96/items.length)},width_mobile:{unit:'%',size:100},flex_direction:'column',background_background:'classic',background_color:'#ffffff',padding:PX(18),border_radius:PX(12),border_border:'solid',border_width:PX(1),border_color:'#D5DBD0'},[H((numbered?(k+1)+'. ':(i.icon?i.icon+' ':''))+i.title,'h3',ac,'right'),T('<p>'+esc(i.text)+'</p>','#12231B','right')],true)),true);
